begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temp table qa_test_state(key text primary key,value uuid);
grant all on qa_test_state to authenticated,service_role;
create function pg_temp.qa_id() returns uuid language sql as $$select value from qa_test_state where key='report'$$;
create function pg_temp.check_id(kind text) returns uuid language sql as $$select id from public.scan_checks where scan_run_id='41111111-1111-4111-8111-111111111111' and check_type=kind$$;
insert into auth.users(id,email) values('11114444-1111-4111-8111-111111111111','report-a@example.test'),('22224444-2222-4222-8222-222222222222','report-b@example.test');
insert into public.projects(id,owner_id,name,website_url) values
 ('31111111-1111-4111-8111-111111111111','11114444-1111-4111-8111-111111111111','Report fixture','http://fixture:8080/current'),
 ('32222222-2222-4222-8222-222222222222','22224444-2222-4222-8222-222222222222','Other project','http://fixture:8080/');
insert into public.domain_verifications(project_id,domain,status,method,verified_at,expires_at)
 values('31111111-1111-4111-8111-111111111111','fixture','verified','local_fixture',now(),now()+interval '24 hours');
insert into public.scan_runs(id,project_id,requested_by,target_url,status,started_at,completed_at,passed_count,failed_count,warning_count)
 values('41111111-1111-4111-8111-111111111111','31111111-1111-4111-8111-111111111111','11114444-1111-4111-8111-111111111111','http://fixture:8080/recorded','completed',now()-interval '8 seconds',now(),3,1,2);
insert into public.scan_checks(scan_run_id,check_type,outcome,description,details,screenshot_path)
 select '41111111-1111-4111-8111-111111111111',kind,
 case when kind in ('availability','desktop','mobile') then 'pass' when kind='links' then 'fail' else 'warning' end,
 'Persisted fixture observation',jsonb_build_object('fixture',true),case when kind in ('desktop','mobile') then '41111111-1111-4111-8111-111111111111/1/'||kind||'.png' else null end
 from unnest(array['availability','desktop','mobile','javascript','links','network']) kind;
insert into storage.objects(bucket_id,name) values('scan-artifacts','41111111-1111-4111-8111-111111111111/1/desktop.png'),('scan-artifacts','41111111-1111-4111-8111-111111111111/1/mobile.png');

update auth.users set email_confirmed_at=now();
insert into auth.users(id,email,email_confirmed_at) values('33334444-3333-4333-8333-333333333333','outsider@example.test',now());
create temp table release_state(key text primary key,value uuid); grant all on release_state to authenticated;
create function pg_temp.review_id(k text default 'v1') returns uuid language sql as $$select value from release_state where key=k$$;
create function pg_temp.invite_id() returns uuid language sql as $$select id from public.review_invitations where review_id=pg_temp.review_id() and status in ('pending','accepted')$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11114444-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into qa_test_state values('report',public.create_qa_report('41111111-1111-4111-8111-111111111111'));
insert into release_state values('finding',pg_temp.check_id('links'));
insert into release_state values('v1',public.create_release_review(pg_temp.qa_id(),'Release v1','<script>untrusted notes</script>','report-b@example.test'));
insert into release_state values('i1',pg_temp.invite_id());
select is((select status from public.release_reviews where id=pg_temp.review_id()),'draft','draft created');
select is((select version from public.release_reviews where id=pg_temp.review_id()),1,'first version');
select is((select snapshot->>'target_url' from public.release_reviews where id=pg_temp.review_id()),'http://fixture:8080/recorded','snapshot uses original scan target');
select is((select jsonb_array_length(snapshot->'findings') from public.release_reviews where id=pg_temp.review_id()),6,'actual checks snapshotted');
select is((select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),(select encode(extensions.digest(convert_to(snapshot::text,'UTF8'),'sha256'),'hex') from public.release_reviews where id=pg_temp.review_id()),'canonical JSON digest');
select throws_ok($$update public.release_reviews set snapshot='{}'$$,'42501',null,'snapshot direct edits denied');
select throws_ok($$delete from public.review_events$$,'42501',null,'audit deletion denied');
select throws_ok($$insert into public.review_decisions(review_id) values(gen_random_uuid())$$,'42501',null,'forged decisions denied');
select is(public.manage_release_review(pg_temp.review_id(),'submit'),pg_temp.invite_id(),'submission returns current invitation');
select is((select status from public.release_reviews where id=pg_temp.review_id()),'pending_review','submitted');
select throws_ok($$select public.manage_release_review(pg_temp.review_id(),'submit')$$,'P0001','invalid_transition','cannot submit twice');
select public.save_qa_triage(pg_temp.qa_id(),pg_temp.check_id('links'),'high','investigating','Later edited note',1,'{}');
select is((select f->>'notes' from public.release_reviews r,jsonb_array_elements(r.snapshot->'findings') f where r.id=pg_temp.review_id() and f->>'type'='links'),'','triage changes do not rewrite snapshot');
select set_config('request.jwt.claims','{"sub":"22224444-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.release_reviews),0,'invited account cannot read before accepting');
select is((select count(*)::int from storage.objects where name like '41111111%'),0,'no evidence before acceptance');
select is(public.accept_review_invitation(pg_temp.invite_id()),pg_temp.review_id(),'matching verified account accepts');
select is((select count(*)::int from public.release_reviews),1,'accepted reviewer reads one snapshot');
select is((select count(*)::int from public.qa_reports),0,'original report stays private');
select is((select count(*)::int from public.scan_runs),0,'scan history stays private');
select is((select count(*)::int from public.projects where id='31111111-1111-4111-8111-111111111111'),0,'project stays private');
select is((select count(*)::int from storage.objects where name like '41111111%'),2,'only exact snapshot artifacts authorized');
select is((select count(*)::int from public.review_events),0,'owner audit not exposed');
insert into release_state values('comment',public.add_review_comment(pg_temp.review_id(),'<img src=x onerror=alert(1)>',pg_temp.review_id('finding'),null,'change_request'));
select is((select author_id from public.review_comments where id=pg_temp.review_id('comment')),auth.uid(),'comment author derived');
select throws_ok($$update public.review_comments set content='rewritten'$$,'42501',null,'cannot rewrite history');
select throws_ok($$select public.add_review_comment(pg_temp.review_id(),'bad finding',gen_random_uuid())$$,'P0001','invalid_finding','wrong finding denied');
select throws_ok($$select public.decide_release_review(pg_temp.review_id(),1,repeat('a',64),'approved',true,true,true,'')$$,'P0001','review_version_mismatch','digest forgery denied');
select throws_ok($$select public.decide_release_review(pg_temp.review_id(),2,(select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),'approved',true,true,true,'')$$,'P0001','review_version_mismatch','wrong version denied');
select throws_ok($$select public.decide_release_review(pg_temp.review_id(),1,(select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),'approved',true,false,true,'')$$,'P0001','acknowledgement_required','failed checks acknowledgement required');
select throws_ok($$select public.decide_release_review(pg_temp.review_id(),1,(select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),'changes_requested',false,false,false,'')$$,'P0001','feedback_required','change request needs notes');
select public.decide_release_review(pg_temp.review_id(),1,(select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),'changes_requested',false,false,false,'Please fix the broken link');
select throws_ok($$select public.decide_release_review(pg_temp.review_id(),1,(select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),'approved',true,true,true,'')$$,'P0001','decision_already_recorded','decision replay denied');
select set_config('request.jwt.claims','{"sub":"11114444-1111-4111-8111-111111111111","role":"authenticated"}',true);
select public.resolve_review_feedback(pg_temp.review_id(),pg_temp.review_id('comment'),true);
select ok((select resolved_at is not null from public.review_comments where id=pg_temp.review_id('comment')),'resolution tracked');
select public.add_review_comment(pg_temp.review_id(),'Developer reply',null,pg_temp.review_id('comment'));
insert into release_state values('v2',public.create_release_review(pg_temp.qa_id(),'Release v2','Updated release','report-b@example.test',pg_temp.review_id()));
select is((select version from public.release_reviews where id=pg_temp.review_id('v2')),2,'new version created');
select is((select count(*)::int from public.review_decisions where review_id=pg_temp.review_id('v2')),0,'decision not carried forward');
select isnt((select snapshot_digest from public.release_reviews where id=pg_temp.review_id()),(select snapshot_digest from public.release_reviews where id=pg_temp.review_id('v2')),'version digest changes');
select throws_ok($$select public.create_release_review(pg_temp.qa_id(),'Branch','notes','report-b@example.test',pg_temp.review_id())$$,'P0001','revision_already_exists','stale revision cannot branch');
select public.manage_release_review(pg_temp.review_id('v2'),'submit');
select set_config('request.jwt.claims','{"sub":"33334444-3333-4333-8333-333333333333","role":"authenticated"}',true);
select is((select count(*)::int from public.release_reviews),0,'third user cannot read');
select is((select count(*)::int from public.review_invitations),0,'third user cannot enumerate invitations');
select is((select count(*)::int from public.review_comments),0,'third user cannot read comments');
select throws_ok($$select public.accept_review_invitation(pg_temp.review_id('i1'))$$,'42501','not_authorized','wrong email denied');
select throws_ok($$select public.create_release_review(pg_temp.qa_id(),'Forged','','report-b@example.test')$$,'42501','not_authorized','cross-project creation denied');
select set_config('request.jwt.claims','{"sub":"22224444-2222-4222-8222-222222222222","role":"authenticated"}',true);
select public.accept_review_invitation((select id from public.review_invitations where review_id=pg_temp.review_id('v2')));
select public.decide_release_review(pg_temp.review_id('v2'),2,(select snapshot_digest from public.release_reviews where id=pg_temp.review_id('v2')),'approved',true,true,true,'Accepted with known failures');
select is((select count(*)::int from public.review_decisions),2,'v1 change request and v2 approval both preserved');
select set_config('request.jwt.claims','{"sub":"11114444-1111-4111-8111-111111111111","role":"authenticated"}',true);
select public.manage_release_review(pg_temp.review_id('v2'),'revoke');
select is((select decision from public.review_decisions where review_id=pg_temp.review_id('v2')),'approved','revocation does not rewrite decision');
insert into release_state values('v3',public.create_release_review(pg_temp.qa_id(),'Release v3','','report-b@example.test',pg_temp.review_id('v2')));
select public.manage_release_review(pg_temp.review_id('v3'),'submit');
insert into release_state values('old_invite',(select id from public.review_invitations where review_id=pg_temp.review_id('v3')));
reset role;
update public.release_reviews set expires_at=now()-interval '1 second' where id=pg_temp.review_id('v3');
update public.review_invitations set expires_at=now()-interval '1 second' where review_id=pg_temp.review_id('v3');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"22224444-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.release_reviews where id=pg_temp.review_id('v2')),0,'accepted invite revocation removes access');
select throws_ok($$select public.accept_review_invitation(pg_temp.review_id('old_invite'))$$,'P0001','invitation_unavailable','expired invitation not accessible');
select set_config('request.jwt.claims','{"sub":"11114444-1111-4111-8111-111111111111","role":"authenticated"}',true);
select public.expire_release_reviews();
select is((select status from public.release_reviews where id=pg_temp.review_id('v3')),'expired','expiry materialized');
insert into release_state values('new_invite',public.manage_release_review(pg_temp.review_id('v3'),'reissue'));
select is((select status from public.release_reviews where id=pg_temp.review_id('v3')),'pending_review','expired review reissued explicitly');
select is((select count(*)::int from public.review_invitations where review_id=pg_temp.review_id('v3')),2,'invitation history preserved');
select ok((select count(*) from public.review_events where event_type='invitation_reissued')>0,'reissue audited');
reset role;
update auth.users set email_confirmed_at=null where id='22224444-2222-4222-8222-222222222222';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"22224444-2222-4222-8222-222222222222","role":"authenticated"}',true);
select throws_ok($$select public.accept_review_invitation(pg_temp.review_id('new_invite'))$$,'42501','not_authorized','unverified email denied');
reset role;
update auth.users set email_confirmed_at=now() where id='22224444-2222-4222-8222-222222222222';
set local role authenticated;
select throws_ok($$select public.accept_review_invitation(pg_temp.review_id('old_invite'))$$,'P0001','invitation_unavailable','reissue never revives old link');
select public.accept_review_invitation(pg_temp.review_id('new_invite'));
reset role;
update public.release_review_evidence set expires_at=now()-interval '1 second';
set local role authenticated;
select ok(not public.can_read_review_evidence('41111111-1111-4111-8111-111111111111/1/desktop.png'),'expired snapshot evidence denied despite review access');
-- Current retention can shorten original expiry; it can never extend the snapshot bound.
select set_config('request.jwt.claims','{"sub":"11114444-1111-4111-8111-111111111111","role":"authenticated"}',true);
select ok((select count(*) from public.review_events where event_type='release_approved')=1,'approval audit preserved');
delete from public.projects where id='31111111-1111-4111-8111-111111111111';
select is((select count(*)::int from public.release_reviews),0,'project deletion removes review access');
reset role;
select is((select count(*)::int from public.review_comments),0,'project feedback cascade');
select is((select count(*)::int from public.review_decisions),0,'project decision cascade');
select is((select count(*)::int from public.review_events),0,'project audit cascade documented');
set local role anon;
select throws_ok($$select * from public.release_reviews$$,'42501',null,'anonymous snapshot denied');
select throws_ok($$select public.accept_review_invitation(gen_random_uuid())$$,'42501',null,'anonymous acceptance denied');
reset role;
select * from finish();
rollback;
